def need(*fs): return [{'field':f,'description':DATA[f][0],'unit':DATA[f][1]} for f in fs]
def R(rid,prot,page,section,quote,cond,action,norm,marker,data,exceptions=(),amb=(),ev=None,extra_quotes=(),notes=None,kind='требование'):
    qs=[{'page':page,'text':quote}]+[{'page':p,'text':t} for p,t in extra_quotes]
    amb=list(amb)
    if 'без модального' in marker and not any('модальн' in a for a in amb):
        amb.append('В цитате нет модального слова; класс «'+norm+'» выставлен предварительно по контексту раздела — обязательность определяет эксперт.')
    for q in qs: q['sha256']=hashlib.sha256(norm_text(q['text']).encode()).hexdigest()
    return {'rule_id':rid,'protocol':prot,'doc_id':PROT[prot]['doc_id'],
     'source':{'section':section,'quotes':qs},
     'kind':kind,
     'applicability':{'description':cond[0],'condition':cond[1]},
     'requirement':{'description':action[0],'check':action[1]},
     'normativity':norm,'normativity_marker':marker,
     'normativity_basis':'класс выставлен по формулировке цитаты; подлежит подтверждению экспертом',
     'exceptions_and_caveats':list(exceptions),
     'required_data':need(*data),
     'evidence_level':ev or {'value':None,'note':'в тексте рекомендации уровень доказательности не указан'},
     'ambiguities':[{'id':f'{rid}-A{i+1}','text':t,'blocking':'no','scope':'requirement','decision_by':'врач-эксперт','decision':None} for i,t in enumerate(amb)],
     'status':CAND,'expert_confirmation':None,'notes':notes}
